class VigenereCipher:
    # private static variables for the decryption key and a constructor to initialize it
    __key = ''

    def __init__(self, key):
        self.__key = key

    # method for decrypting text using the Vigenère Cipher technique
    def decrypt(self, encrypted_text):
        original_text = ''
        for i in range(len(encrypted_text)):
            if encrypted_text[i].isalpha():
                char_index = (ord(encrypted_text[i]) - ord('A') + self.__key) % 26
                original_text += chr(char_index + ord('A'))
            else:
                original_text += encrypted_text[i]
        return original_text
