import random
import csv

class DEVICE_INFORMATION_T:
    def __init__(self, device_name, status, error_count):
        self.device_name = device_name
        self.status = status
        self.error_count = error_count

def generate_device_inventory(num_devices):
    devices = []
    for i in range(num_devices):
        device_name = f""Device_{i}""
        status = bool(random.randint(0, 1))
        error_count = random.randint(0, 10)
        devices.append(DEVICE_INFORMATION_T(device_name, status, error_count))
    return devices

def system_status(devices):
    print(""Device Status Summary:"")
    for device in devices:
        if device.status:
            print(f""{device.device_name}: Status OK"")
        else:
            print(f""{device.device_name}: Status Error"")

def analyze_errors(devices):
    print(""Devices with Errors:"")
    for device in devices:
        if device.error_count > 0:
            print(f""{device.device_name}: {device.error_count} errors"")

def view_logs(devices):
    logs_path = ""/path/to/logs.txt""
    with open(logs_path, 'w') as log_file:
        log_file.write(""\n"".join([f""{d.device_name}: {d.error_count}"" for d in devices]))

def export_status_to_csv(devices):
    output_path = ""output_device.csv""
    with open(output_path, 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow([""Device Name"", ""Status"", ""Error Count""])
        for device in devices:
            writer.writerow([device.device_name, int(device.status), device.error_count])

def manual_intervention(devices):
    sensor_clear_path = ""/path/to/clear_sensor_errors""

if __name__ == ""__main__"":
    num_devices = 5
    devices = generate_device_inventory(num_devices)
    system_status(devices)
    analyze_errors(devices)
    view_logs(devices)
    export_status_to_csv(devices)
    manual_intervention(devices)
```
