    # Perform the necessary checks on hostname before resolving it
    def resolve_hostname(hostname):
        if not isinstance(hostname, str):
            raise TypeError(""Expected a string object"")

        # The actual C function to resolve hostname is used here (not shown) 
        resolved_ip = ctypes.c_uint32()
        ret = some_c_function(ctypes.c_char_p(hostname), ctypes.byref(resolved_ip))

        if not ret:
            raise OSError(""Failed to resolve hostname"")

        return resolved_ip.value

    # Convert the resolved IP address into u_char array
    def convert_ip_to_u_char(ip_address_str):
        if not isinstance(ip_address_str, str):
            raise TypeError(""Expected a string object"")

        ip_bytes = ip_address_str.split('.')
        if len(ip_bytes) != 4:
            raise ValueError(""Invalid IP address format"")

        u_char_array = (ctypes.c_ubyte * 4)()
        for i, byte in enumerate(ip_bytes):
            try:
                u_char_array[i] = ctypes.c_ubyte(int(byte))
            except ValueError as e:
                raise ValueError(""Invalid IP address format"") from e

        return u_char_array

if __name__ == ""__main__"":
    devices = generate_device_inventory(5)

    system_status(devices)
