class UniqueElementSelector:
    def extract_unique_elements(self, my_list):
        unique_elements = []
        for element in my_list:
            if element not in unique_elements:
                unique_elements.append(element)
        return unique_elements

    def remove_duplicates(self, my_list):
        seen = set()
        my_list[:] = [x for x in my_list if x not in seen and not seen.add(x)]
