from typing import Dict

GITHUB_API_URL = ""https://api.github.com""

def fetch_repo_info(repo_url: str) -> Dict[str, int]:
    try:
        response = requests.get(f""{GITHUB_API_URL}/repos{repo_url}"")
        if response.status_code == 200:
            repo_data = response.json()
            return {
                ""stars"": repo_data[""stargazers_count""],
                ""forks"": repo_data[""forks_count""],
                ""watchers"": repo_data[""watchers_count""],
            }
        else:
            raise Exception(f""API request failed with status code {response.status_code}"")
    except requests.exceptions.RequestException as e:
        print(f""An error occurred during the API request: {e}"")
    except Exception as e:
        print(f""An unexpected error occurred: {e}"")

def validate_repo_url(repo_url: str) -> bool:
    if not repo_url.startswith(""https://github.com/""):
        print(""Invalid repository URL. Please provide a valid GitHub repository URL."")
        return False
    return True

def main():
    repo_url = input(""Please enter the GitHub repository URL: "")

    if validate_repo_url(repo_url):
        info = fetch_repo_info(repo_url)

        if info:
            print(f""\nRepository Information:"")
            for metric, value in info.items():
                print(f""{metric.capitalize()}: {value}"")

if __name__ == ""__main__"":
