import yaml

def extractAPIKeyFromYAML(yaml_file_path):
    try:
        with open(yaml_file_path, 'r') as file:
            data = yaml.load(file)
    except FileNotFoundError:
        return None
    except yaml.YAMLError:
        return None

    if ""API"" not in data:
        return None

    api_object = data[""API""]

    if ""key"" not in api_object:
        return None

    api_key = api_object[""key""]

    if len(api_key) == 0:
        return None

    return api_key
```
