import re

class MathExpression:
    def __init__(self, expression):
        self.expression = expression

    @property
    def evaluate(self, x):
        return eval(self.expression, {'x': x})

# Example usage:
expressions = {
    'f1': MathExpression('2*x + 3'),
    'f2': MathExpression('x**2 - 4')
}

# Compute the value of function f1 at x=5
print(expressions['f1'].evaluate(5)) # Output: 13

# Compute the value of function f2 at x=2
print(expressions['f2'].evaluate(2)) # Output: 4
