# Define a class to generate socket information
class SocketInformationGenerator:
    def __init__(self, ip_list, port_range):
        self.ip_list = ip_list
        self.port_range = port_range

    # Generate an array of socket information objects
    def generate_socket_info(self):
        socket_info_array = []
        for _ in range(len(self.ip_list)):
            ip = random.choice(self.ip_list)
            port = random.randint(*self.port_range)
            connection_status = 'connected' if random.random() > 0.5 else 'disconnected'
            socket_info_array.append({'IP': ip, 'Port': port, 'Status': connection_status})
        return socket_info_array

