def fetch_repo_info(repo_url: str) -> Dict[str, int]:
    try:
        response = requests.get(f""{GITHUB_API_URL}/repos{repo_url}"")
        if response.status_code == 200:
            repo_data = response.json()
            return {
                ""stars"": repo_data[""stargazers_count""],
