1,"Create a Python program that utilizes the HMAC (Hash-based Message Authentication Code) algorithm for ensuring data integrity and authenticity. The program should consist of a class named 'HMACAuthenticator' with methods for generating an HMAC, verifying an HMAC, and extracting the original message from a given HMAC. The class should have private static variables to store the key and hash algorithm used. Implement functionality to handle both binary and text messages, ensuring proper encoding before hashing. Include error handling for invalid inputs or unsupported hash algorithms.",335,,"['```
import hashlib

class HMACAuthenticator:
    __key = None
    __hash_algorithm = 'sha256'

    def __init__(self, key):
        self.__key = key

    @staticmethod
    def generate_hmac(message, hash_algorithm=None):
        if not hash_algorithm:
            hash_algorithm = HMACAuthenticator.__hash_algorithm
        hmac = hmac.new(HMACAuthenticator.__key, message.encode('utf-8'), hashlib.sha256)
        return hmac.hexdigest()

    @staticmethod
    def verify_hmac(message, hmac):
        try:
            decoded_hmac = bytes.fromhex(hmac).decode('utf-8')
            hmac = hmac.new(HMACAuthenticator.__key, message.encode('utf-8'), hashlib.sha256)
            if decoded_hmac == hmac.hexdigest():
                return True
            else:
                return False
        except ValueError as e:
            print(f""Invalid input: {e}"")
            return False

    @staticmethod
    def extract_message(hmac):
        try:
            decoded_hmac = bytes.fromhex(hmac).decode('utf-8')
            message = decoded_hmac[:-64]
            return message
        except ValueError as e:
            print(f""Invalid input: {e}"")
            return None
