import sys
from datetime import datetime

def main():
    if len(sys.argv) < 2:
        print(""Usage: python count_files.py <directory> [-d|--detailed] [-p|--print]"")
        return

    input_dir = sys.argv[1]
    detailed = False
    output_file = None

    for arg in sys.argv[2:]:
        if arg == ""-d"" or arg == ""--detailed"":
            detailed = True
        elif arg == ""-p"" or arg == ""--print"":
            output_file = open(""output.txt"", ""w"")

    file_count = count_files(input_dir)
    if detailed:
        print_stats(input_dir, file_count)
    else:
        print(f""Found {file_count} files in {input_dir}"")

    if output_file is not None:
        with open(""output.txt"", ""w"") as f:
            f.write(f""Found {file_count} files in {input_dir}"")

def count_files(directory):
    file_count = 0
    for root, dirs, files in os.walk(directory):
