import bcrypt

class PasswordHasher:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def hash_password(self, password):
        return bcrypt.hashpw(password, self.secret_key)

    def verify_password(self, password, hashed_password):
        return bcrypt.checkpw(password, hashed_password)

    def cleanup(self):
        bcrypt.deallocate()

# interface for setting a secret key and applying environment-specific configurations
secret_key = input(""Enter your secret key: "")
hasher = PasswordHasher(secret_key)

# use the hasher to hash a password
password = ""my_password""
hashed_password = hasher.hash_password(password)
print(""The hashed password is"", hashed_password)

# verify the password using the same hasher and secret key
if hasher.verify_password(password, hashed_password):
    print(""The password is correct"")
else:
    print(""The password is incorrect"")

# cleanup the hasher when finished
hasher.cleanup()
```
