// FileSystem is a structure to hold information about the file system
type FileSystem struct {
	RootDir string
}

// NewFileSystem returns a new instance of FileSystem with the specified root directory
func NewFileSystem(rootDir string) *FileSystem {
	return &FileSystem{
		RootDir: rootDir,
	}
}

// Traverse traverses the file system from the root directory and returns the list of files and directories
func (fs *FileSystem) Traverse() ([]string, error) {
	var files []string

	err := filepath.Walk(fs.RootDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		files = append(files, path)
		return nil
	})

	if err != nil {
		return nil, err
	}

	return files, nil
}

