class SocketInformationGenerator:
    def __init__(self, ip_addresses, port_range):
        self.ip_addresses = ip_addresses
        self.port_range = port_range

    @staticmethod
    def validate_input(ip_address, port):
        if not re.match(r'^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$', ip_address):
            raise ValueError('Invalid IP address')
        if not (1 <= port <= 65535):
            raise ValueError('Port number must be between 1 and 65535')
        return True

    def generate_socket_info(self):
        sockets = []
        for ip_address in self.ip_addresses:
            for port in range(self.port_range[0], self.port_range[1] + 1):
                try:
                    SocketInformationGenerator.validate_input(ip_address, port)
                    sockets.append({'ip_address': ip_address, 'port': port, 'status': 'connected'})
                except ValueError as e:
                    print(f'{e} {ip_address}:{port}')
        return sockets

