import sys
import os
import re
from collections import Counter

def analyze_unique_words(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            content = file.read().lower()
            words = re.findall(r'\b\w+\b', content)
            unique_words = set(words)
            return len(unique_words)
    except FileNotFoundError:
        print(f""Error: File '{file_path}' not found."")
        sys.exit(1)
    except Exception as e:
        print(f""Error: {e}"")
        sys.exit(1)

def filter_specific_chars(file_path, chars):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            content = file.read()
            filtered_content = ''.join([c for c in content if c not in chars])
            return filtered_content
    except FileNotFoundError:
        print(f""Error: File '{file_path}' not found."")
        sys.exit(1)
    except Exception as e:
        print(f""Error: {e}"")
        sys.exit(1)

def display_usage():
    print(""Usage:"")
    print(""-ta [file] - Analyze the text content of the specified file and output the number of unique words."")
    print(""-ft [file] <chars> - Filter out and output only specific characters from the specified input file."")
    print(""--help - Display this usage guide."")

if __name__ == ""__main__"":
    if len(sys.argv) < 2 or ""--help"" in sys.argv[1:]:
        display_usage()
        sys.exit(0)

    options = {
        ""-ta"": analyze_unique_words,
        ""-ft"": filter_specific_chars,
    }

    for arg in sys.argv[1:]:
        if arg in options:
            option, *args = arg.split(maxsplit=1)
            if option == ""-ft"":
                if len(args) != 2 or args[0].endswith("",""):
                    print(""Invalid format for -ft option. Please provide a valid file path and comma-separated list of characters to filter out."")
                    display_usage()
                    sys.exit(1)
                result = options[option](args[0], args[1])
                output_file_name, *output_args = args[-1].split("","") if "","" in args[-1] else []
                output_file_name += "".out""
                with open(output_file_name, ""w"", encoding=""utf-8"") as output_file:
                    output_file.write(result)
    sys.exit(0)']",0,[0],[],True,0,0,0,

